# Решение владельца 14.11 («Всё принимаю», вопрос 2 — вариант А): на кнопке подтверждения — действие
# с суммой, в тексте — строка «Причина» (так в коде). Образец «Подтверждение» остаётся для сравнения.
def _confirm(key, sid, button, reason):
    for st in G[key]["states"]:
        if st["id"] == sid:
            st["name"] = "Подтверждение · решение 14.11"
            st["rich"] = st["rich"].replace("\n" + SIXTY, "\nПричина: <i>" + reason + "</i>\n" + SIXTY)
            st["keys"] = [[["danger", button[0], button[1]], ["", "close", "Отмена"]]]
_confirm("ops_intake", "c", ("done", "Зачислить 30.00"), "деньги в чате кошелька, ответа не было")
_confirm("ops_paid", "c", ("done", "Отметить выплаченной"), "чек нашёлся в истории кошелька")
_confirm("ops_capital", "out", ("ack", "Провести вывод 12.00"), "выводил сам, мимо бота")
_confirm("ops_capital", "in", ("ack", "Провести взнос 120.00"), "пополнил резерв сам")

